import * as React from 'react';
import Box from '@mui/material/Box';
import Grid from '@mui/material/Unstable_Grid2';
import GridCard from './word-game-components/GridCard';
import { IWord } from '../data/Words';
import Buttons from './word-game-components/Buttons'; 
import GridCategory from './word-game-components/GridCategory';
import Alert from '@mui/material/Alert';
import Confetti from 'react-confetti';
import {useWindowSize} from 'react-use';
import Mistakes from './word-game-components/Mistakes';
import { CircularProgress, IconButton, Stack } from '@mui/material';
import HomeIcon from '@mui/icons-material/Home';
import axios from 'axios';
import { useEffect, useRef } from 'react';

export interface IWordGameProps {
    onClickHome: () => void;
};

interface IGameData {
    words: Array<IWord>;
    selectedWords: Set<IWord>;
    remainingWords: Array<IWord>;
    solvedCategories: string[];
    submissionResult: string | undefined;
    hasWon: boolean;
    numMistakesLeft: number;
    isError: boolean;
    gameNumber: number;
    extraCriteria: string | undefined;
    pastContents: Array<any>;
}

export default function DynamicWordGame(props: IWordGameProps) {
    const { onClickHome } = props;
    const {width, height} = useWindowSize();
    const [gameData, setGameData] = React.useState<IGameData>({
        words: [],
        selectedWords: new Set<IWord>(),
        remainingWords: [],
        solvedCategories: [],
        submissionResult: undefined,
        hasWon: false,
        numMistakesLeft: 5,
        isError: false,
        gameNumber: 1,
        extraCriteria: undefined,
        pastContents: [],
    })
    const renderCount = useRef(0);

    useEffect(() => {
        renderCount.current = renderCount.current + 1;
    });

    const useFetchWords = () => {

        useEffect(() => {
            const fetchWords = async () => {

            try {
            if (renderCount.current <= 1) {
                const apiKey = process.env['REACT_APP_GEMINI_API_KEY'];

                const extraCriteriaPrefix = "Additional criteria: \n 1. ";
                const prompt = 
                `Pretend you are creating the New York Times Connections game. Connections is a word game that challenges players to find categories amongst words. Players are given 16 words and they must find 4 categories with 4 words each.
                Each puzzle has exactly one solution and is meant to be tricky by having words that could fit into multiple categories. However, every solution must only have 4 categories with 4 words in each category.
                Criteria for the categories:  
                1. Try to make the categories very difficult like the examples below:
                a. Category: "CONCOCTION". Words: "COCKTAIL","COMPOUND","MIXTURE","SOLUTION"
                b. Category: "TYPES OF SENTENCES". Words: "COMMAND","EXCLAMATION","QUESTION","STATEMENT"
                d. Category: "COMPLAINT HOMOPHONES". Words: "GROWN","MOWN","WHALE","WINE"
                n. Category: "KINDS OF PAPER". Words: "CONSTRUCTION","GRAPH","TISSUE","WAX"
                o. Category: "WORDS PRECEDED BY 'CANDY'". Words: "CORN","CANE","LAND","CRUSH"
                s. Category: "CLASSIC JOKE STAPLES". Words: "BAR","CHICKEN","KNOCK-KNOCK","LIGHT BULB"
                2. There must be 4 distinct categories (no repeats).
                3. VERY IMPORTANT: At least 3 words should fit with more than one category to make it difficult for players to group the words.
                Criteria for the words:
                1. There must be 16 distinct words (no repeats) and exactly 4 words per category.
                Criteria for the response: 
                1. Respond to this prompt with with an array of 16 JSON objects where each JSON object has two keys: the first key is "word" and the value will be the word from one of the 16 words and the second key is "category" and the value will be the description of one of the 4 categories. 
                2. Respond with just a string representation of the array with no triple backticks.
                3. VERY IMPORTANT: Make sure that the words are unique and have not been used in previous responses you have provided.
                4. VERY IMPORTANT: Make sure that the categories are unique and have not been used in previous responses you have provided.
                5. VERY IMPORTANT: Make sure there are only 16 words and only 4 category descriptions in the response.
                ${gameData.extraCriteria ? extraCriteriaPrefix+gameData.extraCriteria: ""}`;
                const response = await axios.post(
                    `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${apiKey}`,
                    {
                      contents:  gameData.pastContents?.concat([{ parts: [{ text: prompt }], role: "user" }]),
                    },
                    {
                      headers: {
                        'Content-Type': 'application/json',
                      },
                    }
                  );
        
                const data = response.data.candidates[0].content.parts[0].text;
                const parsedData = JSON.parse(data); 
                console.log(parsedData);
                const setOfWords = new Set();
                const categoryCounter = new Map();
                parsedData.forEach((obj: IWord) => {
                    if (!setOfWords.has(obj.word)) {
                        const count = categoryCounter.get(obj.category);
                        if (count) {
                            categoryCounter.set(obj.category, count + 1);
                            setOfWords.add(obj.word);
                        }
                        else {
                            categoryCounter.set(obj.category, 1);
                            setOfWords.add(obj.word);
                        }
                    }
                });
                if (setOfWords.size !== 16) {
                    throw new Error();
                }

                categoryCounter.forEach((_value, key) => {
                    if (categoryCounter.get(key) !== 4) {
                        throw new Error();
                    }
                });

                for (let i = parsedData.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    const temp = parsedData[i];
                    parsedData[i] = parsedData[j];
                    parsedData[j] = temp;
                  }
                
                    setGameData({
                        words: parsedData,
                        selectedWords: new Set<IWord>(),
                        remainingWords: parsedData,
                        solvedCategories: [],
                        submissionResult: undefined,
                        hasWon: false,
                        numMistakesLeft: 5,
                        isError: false,
                        gameNumber: gameData.gameNumber,
                        extraCriteria: gameData.extraCriteria,
                        pastContents: gameData.pastContents.concat([{ parts: [{ text: prompt }], role: "user" }, { parts: [{ text: data }], role: "model"}])
                    });
                }
            }
            catch {
                setGameData({
                    words: [],
                    selectedWords: new Set<IWord>(),
                    remainingWords: [],
                    solvedCategories: [],
                    submissionResult: undefined,
                    hasWon: false,
                    numMistakesLeft: 5,
                    isError: true,
                    gameNumber: gameData.gameNumber,
                    extraCriteria: gameData.extraCriteria,
                    pastContents: gameData.pastContents,
                });
            }
        };

            fetchWords();
        }, [gameData.gameNumber])
    };

    useFetchWords();

    const onGridCardSelected = (word: IWord) => {
        if ((!gameData.selectedWords || !gameData.selectedWords.has(word)) && !(gameData.selectedWords.size >= 4)) {
            setGameData(
                {
                    words: gameData.words,
                    selectedWords: new Set(gameData.selectedWords).add(word),
                    remainingWords: gameData.remainingWords,
                    solvedCategories: gameData.solvedCategories,
                    submissionResult: gameData.submissionResult,
                    hasWon: gameData.hasWon,
                    numMistakesLeft: gameData.numMistakesLeft,
                    isError: gameData.isError,
                    gameNumber: gameData.gameNumber,
                    extraCriteria: gameData.extraCriteria,
                    pastContents: gameData.pastContents,
                }
            );
            return;
        }

        const newSelectedWords = new Set(gameData.selectedWords);
        newSelectedWords.delete(word);
        setGameData(
            {
                words: gameData.words,
                selectedWords: newSelectedWords,
                remainingWords: gameData.remainingWords,
                solvedCategories: gameData.solvedCategories,
                submissionResult: undefined,
                hasWon: gameData.hasWon,
                numMistakesLeft: gameData.numMistakesLeft,
                isError: gameData.isError,
                gameNumber: gameData.gameNumber,
                extraCriteria: gameData.extraCriteria,
                pastContents: gameData.pastContents,
            }
        );
    }

    const onShuffle = () => {
        const newRemainingWords = gameData.remainingWords.sort(() => Math.random() - 0.5); 
        setGameData(
            {
                words: gameData.words,
                selectedWords: gameData.selectedWords,
                remainingWords: newRemainingWords,
                solvedCategories: gameData.solvedCategories,
                submissionResult: gameData.submissionResult,
                hasWon: gameData.hasWon,
                numMistakesLeft: gameData.numMistakesLeft,
                isError: gameData.isError,
                gameNumber: gameData.gameNumber,
                extraCriteria: gameData.extraCriteria,
                pastContents: gameData.pastContents,
            }
        );
    }

    const onDeselectAll = () => {
        const newSelectedWords = new Set<IWord>();
        setGameData(
            {
                words: gameData.words,
                selectedWords: newSelectedWords,
                remainingWords: gameData.remainingWords,
                solvedCategories: gameData.solvedCategories,
                submissionResult: undefined,
                hasWon: gameData.hasWon,
                numMistakesLeft: gameData.numMistakesLeft,
                isError: gameData.isError,
                gameNumber: gameData.gameNumber,
                extraCriteria: gameData.extraCriteria,
                pastContents: gameData.pastContents,
            }
        );
    }

    const canSubmit = () => !!(gameData.selectedWords && gameData.selectedWords.size === 4);

    const onSubmit = () => {
        const submittedCategoryCount = new Map();
        if (gameData.selectedWords) {
            Array.from(gameData.selectedWords).forEach(word => {
                const existingEntry = submittedCategoryCount.get(word.category);
                if (existingEntry) {
                    submittedCategoryCount.set(word.category, existingEntry+1)
                } else {
                    submittedCategoryCount.set(word.category, 1)
                }
            });

            if (submittedCategoryCount.size === 1) {
                // update remaining words
                const newRemainingWords = new Set(gameData.remainingWords);
                Array.from(gameData.selectedWords).forEach(word => {
                    newRemainingWords.delete(word);
                });

                // update solved categories
                const newSolvedCategories = gameData.solvedCategories;
                newSolvedCategories.push(Array.from(submittedCategoryCount.keys())[0]);

                // update selected set
                const newSelectedWords = new Set<IWord>();

                // update submission result
                const newSubmissionResult = "You got it!"

                // you won!
                let newHasWon = false;
                if (newSolvedCategories.length === 4) {
                    newHasWon = true;
                }

                setGameData(
                    {
                        words: gameData.words,
                        selectedWords: newSelectedWords,
                        remainingWords: Array.from(newRemainingWords),
                        solvedCategories: newSolvedCategories,
                        submissionResult: newSubmissionResult,
                        hasWon: newHasWon,
                        numMistakesLeft: gameData.numMistakesLeft,
                        isError: gameData.isError,
                        gameNumber: gameData.gameNumber,
                        extraCriteria: gameData.extraCriteria,
                        pastContents: gameData.pastContents,
                    }
                );
            }

            else {
                if (gameData.numMistakesLeft === 1) {
                    // update remaining words
                    const newRemainingWords = new Array<IWord>();

                    // update solved categories
                    const solvedCategories = gameData.solvedCategories;
                    const unsolvedCategories: string[] = [];
                    Array.from(gameData.words).forEach(word => {
                        if (!solvedCategories.includes(word.category) && !unsolvedCategories.includes(word.category)) {
                            unsolvedCategories.push(word.category);
                        }
                    });
                    const newSolvedCategories = solvedCategories.concat(unsolvedCategories);

                    // update selected set
                    const newSelectedWords = new Set<IWord>();

                    // update submission result
                    const newSubmissionResult = "Game over :("

                    setGameData(
                        {
                            words: gameData.words,
                            selectedWords: newSelectedWords,
                            remainingWords: newRemainingWords,
                            solvedCategories: newSolvedCategories,
                            submissionResult: newSubmissionResult,
                            hasWon: gameData.hasWon,
                            numMistakesLeft: gameData.numMistakesLeft-1,
                            isError: gameData.isError,
                            gameNumber: gameData.gameNumber,
                            extraCriteria: gameData.extraCriteria,
                            pastContents: gameData.pastContents,
                        }
                    );
                }

                else if (submittedCategoryCount.size === 2) {
                    const counts = Array.from(submittedCategoryCount.values());
                    if (counts.includes(1) && counts.includes(3)) {
                        // update submission result
                        const newSubmissionResult = "One away!"
    
                        setGameData(
                            {
                                words: gameData.words,
                                selectedWords: gameData.selectedWords,
                                remainingWords: gameData.remainingWords,
                                solvedCategories: gameData.solvedCategories,
                                submissionResult: newSubmissionResult,
                                hasWon: gameData.hasWon,
                                numMistakesLeft: gameData.numMistakesLeft-1,
                                isError: gameData.isError,
                                gameNumber: gameData.gameNumber,
                                extraCriteria: gameData.extraCriteria,
                                pastContents: gameData.pastContents,
                            }
                        );
                    } else {
                        // update submission result
                        const newSubmissionResult = "Nice try!"
    
                        setGameData(
                            {
                                words: gameData.words,
                                selectedWords: gameData.selectedWords,
                                remainingWords: gameData.remainingWords,
                                solvedCategories: gameData.solvedCategories,
                                submissionResult: newSubmissionResult,
                                hasWon: gameData.hasWon,
                                numMistakesLeft: gameData.numMistakesLeft-1,
                                isError: gameData.isError,
                                gameNumber: gameData.gameNumber,
                                extraCriteria: gameData.extraCriteria,
                                pastContents: gameData.pastContents,
                            }
                        );
                    }
                }
    
                else {
                    // update submission result
                    const newSubmissionResult = "Nice try!"
    
                    setGameData(
                        {
                            words: gameData.words,
                            selectedWords: gameData.selectedWords,
                            remainingWords: gameData.remainingWords,
                            solvedCategories: gameData.solvedCategories,
                            submissionResult: newSubmissionResult,
                            hasWon: gameData.hasWon,
                            numMistakesLeft: gameData.numMistakesLeft-1,
                            isError: gameData.isError,
                            gameNumber: gameData.gameNumber,
                            extraCriteria: gameData.extraCriteria,
                            pastContents: gameData.pastContents,
                        }
                    );
                }
            }
        }
    }

    const onNewGame = () => {
        renderCount.current = 0;
        setGameData(
            {
                words: [],
                selectedWords: new Set<IWord>(),
                remainingWords: [],
                solvedCategories: [],
                submissionResult: undefined,
                hasWon: false,
                numMistakesLeft: 5,
                isError: false,
                gameNumber: gameData.gameNumber + 1,
                extraCriteria: gameData.extraCriteria,
                pastContents: gameData.pastContents,
            }
        );
    }

    const onClickAddCriteria = (criteria: string | undefined) => {
        if (criteria) {
            setGameData(
                {
                    words: gameData.words,
                    selectedWords: gameData.selectedWords,
                    remainingWords: gameData.remainingWords,
                    solvedCategories: gameData.solvedCategories,
                    submissionResult: gameData.submissionResult,
                    hasWon: gameData.hasWon,
                    numMistakesLeft: gameData.numMistakesLeft,
                    isError: gameData.isError,
                    gameNumber: gameData.gameNumber,
                    extraCriteria: criteria,
                    pastContents: gameData.pastContents,
                }
            );
        }
    }

    return (
    <>
        <Stack direction="row" spacing={4} sx={{margin: 3, display:"flex", justifyContent:"start"}}>
            <IconButton onClick={onClickHome}>
                <HomeIcon htmlColor="dimgray"/>
            </IconButton>
        </Stack>
        {!gameData.isError && gameData.words.length === 0 && <CircularProgress size="50px" sx={{margin: 3, color: "steelblue"}}/>}
        {!gameData.isError && gameData.words.length > 0 &&
        <> 
            <Box sx={{display:"flex", justifyContent:"center", margin: 2}}>
            <Grid container spacing={2} columns={4} sx={{width: 330, height: 330}}>
                {gameData.solvedCategories.map((category, index) => (
                <Grid xs={4} key={index}>
                    <GridCategory category={category}></GridCategory>
                </Grid>
                ))}
                {gameData.remainingWords.map((word, index) => (
                <Grid xs={1} key={index}>
                    <GridCard word={word} isSelected={!!(gameData.selectedWords && gameData.selectedWords.has(word))} onSelected={onGridCardSelected}></GridCard>
                </Grid>
                ))}
            </Grid>
            </Box>
            <Mistakes numMistakesLeft={gameData.numMistakesLeft}></Mistakes>
            <Buttons canSubmit={canSubmit()} onSubmit={onSubmit} onDeselectAll={onDeselectAll} onShuffle={onShuffle} onNewGame={onNewGame} onClickAddCriteria={onClickAddCriteria} extraCriteria={gameData.extraCriteria}></Buttons>
            <Box sx={{display:"inline-block", marginTop: 3, justifyContent:"center", width: 330}}>
            {(gameData.submissionResult === "Game over :(") ? <Alert severity="error">{gameData.submissionResult}</Alert> 
                    : (gameData.submissionResult === "You got it!") ? <Alert severity="success">{gameData.submissionResult}</Alert> 
                    : (gameData.submissionResult === "One away!") ?  <Alert severity="info">{gameData.submissionResult} {gameData.numMistakesLeft} {gameData.numMistakesLeft >1 ? "mistakes" : "mistake"} remaining</Alert> 
                    : (gameData.submissionResult === "Nice try!") ? <Alert severity="error">{gameData.submissionResult} {gameData.numMistakesLeft} {gameData.numMistakesLeft >1 ? "mistakes" : "mistake"} remaining</Alert> 
                    : undefined}
            </Box>
            {gameData.hasWon ? <Confetti width={width} height={height} /> : undefined}
        </> }
        {gameData.isError && 
            <>
            <Alert severity="error"> Sometimes AI doesn't work. Please try again.</Alert>
            <Buttons onNewGame={onNewGame} onClickAddCriteria={onClickAddCriteria} extraCriteria={gameData.extraCriteria}></Buttons>
            </>
        }
    </>
  );
}
