import * as React from 'react';
import Button from '@mui/material/Button';
import Stack from '@mui/material/Stack';
import { styled } from '@mui/material/styles';
import { TextField } from '@mui/material';
import { inherits } from 'util';


interface IButtonProps {
 canSubmit?: boolean;
 onSubmit?: () => void;
 onDeselectAll?: () => void;
 onShuffle?: () => void;
 onNewGame?: () => void;
 onClickAddCriteria?: (criteria: string | undefined) => void;
 extraCriteria?: string;
}

const StyledButton = styled(Button)(() => ({
    '&.MuiButton-root': {
        fontSize: 11, 
    },
  }));

export default function Buttons(props: IButtonProps) {
    const { canSubmit, onSubmit, onDeselectAll, onShuffle, onNewGame, onClickAddCriteria, extraCriteria } = props;
    const [criteria, setCriteria] = React.useState<string | undefined>(extraCriteria);
    
    const onAddCriteria = () => {
        onClickAddCriteria!(criteria);
        setCriteria(undefined);
    }
    return (
        <>
        { onSubmit && onDeselectAll && onShuffle? 
                <Stack direction="row" spacing={2} sx={{marginTop: 3, display:"flex", justifyContent:"center"}}>
                <StyledButton variant="outlined" sx={{fontSize: 11, color: "rgba(0, 0, 0, 0.54)", border: "1px solid rgba(0, 0, 0, 0.54)"}} onClick={onShuffle}>Shuffle</StyledButton>
                <StyledButton variant="outlined" sx={{fontSize: 11, color: "rgba(0, 0, 0, 0.54)", border: "1px solid rgba(0, 0, 0, 0.54)"}} onClick={onDeselectAll}>Deselect All</StyledButton>
                <Button variant="outlined" sx={{fontSize: 11, color: "rgba(0, 0, 0, 0.54)", border: "1px solid rgba(0, 0, 0, 0.54)"}} disabled={!canSubmit} onClick={onSubmit}>
                    Submit
                </Button>
                </Stack>
        : undefined }
        {onClickAddCriteria ? 
            <>
                <Stack direction="row" spacing={2} sx={{marginTop: 3, display:"flex", justifyContent:"center", alignItems:"flex-end"}}>
                    <TextField
                        id="text-field-1"
                        multiline={true}
                        label={"Add game criteria"}
                        type="text"
                        variant="filled"
                        value={criteria}
                        onInput={e => setCriteria((e.target as HTMLInputElement).value)}
                        sx={{
                            '.MuiFilledInput-root': { background: "white" },
                            '.MuiFilledInput-root.Mui-focused': { background: "white" },
                            '.MuiFilledInput-root:hover': { background: "white" },
                            '.MuiInputBase-input': { fontSize: '11px', paddingTop: "10px"},
                            '.MuiInputLabel-root': { fontSize: '11px'},
                            '.MuiInputLabel-shrink': { fontSize: '14px'},
                            width: "200px", 
                          }}                
                    />
                    <Button variant="outlined" sx={{fontSize: 11, color: "dimgray", border: "1px solid dimgray"}} onClick={onAddCriteria}>Add Criteria</Button>
                </Stack>
            </>   
        :  undefined}
        {onNewGame ? <Stack direction="row" spacing={2} sx={{marginTop: 3, display:"flex", justifyContent:"center"}}>
        <StyledButton variant="contained" sx={{fontSize: 11, color: "white", background: "cornflowerblue", fontWeight: "bold"}} onClick={onNewGame}>Try Again</StyledButton>
        </Stack> : undefined}
        </>
    );
}
